class VersionError (ValueError):
    pass

def check_ex ():
    v = sys.version_info
    if v.major == 3:
        if v.minor < 3 or (v.minor == 3 and v.micro < 4):
            raise VersionError("Error: this is Python 3.{}.{}, not 3.3.4+".format(v.minor, v.micro))
