        if v.minor < 7:
            raise VersionError("Error: this is Python 2.{}, not 2.7".format(v.minor))
    else:
        raise VersionError("Error: this is Python {}, not 2.7 nor 3.x".format(v.major))

def check ():
    try:
        check_ex()
    except VersionError as e:
        print(e.args, file=sys.stderr)
