import os

import pytest
import requests


@pytest.fixture
def url():
    return os.getenv("SITE", "http://localhost:5000")


def test_post_images(expect, url):
    params = {"key": "iw", "lines": ["test", "deployment"]}
    response = requests.post(f"{url}/api/images", json=params)
    expect(response.status_code) == 201
    expect(response.json()["url"]).endswith("/api/images/iw/test/deployment.png")


def test_get_image(expect, url):
    response = requests.get(f"{url}/iw/tests_code/in_production.jpg")
    expect(response.status_code) == 200
    expect(response.headers["Content-Type"]) == "image/jpeg"


def test_post_custom_image(expect, url):
    with open("./tests/images/test.jpg", "rb") as image_file:
        file = {"file": ("test.jpg", image_file, "image/jpg")}
        params = {"key": "do", "lines": ["t", "d"]}
        response = requests.put(f"{url}/api/images", files=file, json=params)
        expect(response.status_code) == 201
        expect(response.json()["url"]).endswith("/api/images/do/t/d.png")

    # cleanup
    os.system(f"sudo {url}/api/images do/t/d")

import os

import pytest
import requests


@pytest.fixture
def url():
    return os.getenv("SITE", "http://localhost:5000")


def test_post_images(expect, url):
    params = {"key": "iw", "lines": ["test", "deployment"]}
    response = requests.post(f"{url}/api/images", json=params)
    expect(response.status_code) == 201
    expect(response.json()["url"]).endswith("/api/images/iw/test/deployment.png")


def test_get_image(expect, url):
    response = requests.get(f"{url}/iw/tests_code/in_production.jpg")
    expect(response.status_code) == 200
    expect(response.headers["Content-Type"]) == "image/jpeg"


def test_post_custom_image(expect, url):
    with pytest.raises(TypeError):
        params = {"key": "iw", "lines": ["custom", "image"], "font-color": "#fff"}
        requests.post(f"{url}/api/images", json=params)

    params = {"key": "iw", "lines": ["custom", "image"], "background": "#28a745"}
    response = requests.post(f"{url}/api/images", json=params)
    expect(response.status_code) == 201
    expect(response.json()["url"]).endswith("/api/images/iw/custom/image.png")

    response = requests.get(f"{url}/api/images/iw/custom/image.png")
    expect(response.status_code) == 200
    expect(response.headers["Content-Type"]) == "image/png"

