register = template.Library()

class BootstrapURLNode(template.Node):
    def __init__(self, url_if_exists, url_if_404, vars=None):
        self.url_if_exists = template.Variable(url_if_exists)
        self.url_if_404 = url(template.Variable(url_if_404))
        self.vars = vars or []

    def render(self, context):
        try:
            value = self.url_if_exists.resolve(context)
        except template.VariableDoesNotExist:
            value = None
        kwargs = {}
        for var in self.vars:
            var_k, var_v = var.split('=')
            if var_v:
                if var_v in context:
                    kwargs[var_k] = template.Variable(var_v).resolve(context)
            if var_k in context:
                kwargs = context[var_k]
        try:
            if value:
                rv = reverse_no_exceptions(value, **kwargs)
            else:
                rv = self.url_if_404.render(context)
        except:
            rv = '#'
        return rv

@register.tag
def bootstrap_url(parser, token):
    """
    {% bootstrap_url '' '' %}
    Generates a URL using reverse. If the URL cannot be reversed, will use
    the URL given in the second parameter. Optional third parameter allows
    you to pass parameters to reverse:
    {% bootstrap_url 'costs' 'generic_404' 'year=%s' %}
    will reverse the 'costs' URL if possible, passing the 'year' parameter
    the value of the 'year' variable, or using the 'year' parameter as a
    fallback if 'year' variable is not found.
    """
    bits = token.contents.split()[1:]
    if len(bits) >= 2:
        url_if_404 = bits[1]
    else:
        url_if_404 = '#'
    vars = bits[2:]
    return BootstrapURLNode(bits[0], url_if_404, vars)

