def optional_url(parser, token):
    """
    {% url opt [viewname] [args [kwargs]] %}

    The given viewname is reverse-resolved according to the normal url
    resolution rules.  If the reverse resolution fails or any of the
    arguments coefficients an exception, then the fragment '#' is
    returned.  Otherwise, the result of the url resolution is returned.

    No other tags or filters may be used in the arguments of this 'url' tag.
    """
    bits = token.split_contents()
    args = []
    kwargs = {}
    rest = bits[1:]
    while rest:
        if rest[0] == ',':
            rest.pop(0)
            continue
        try:
            if '=' in rest[0]:
                # keyword argument
                arg, val = rest[0].split('=', 1)
                if arg != 'opt':
                    raise VariableDoesNotExist
                rest.pop(0)
                continue
            args.append(Variable(rest[0]))
            rest.pop(0)
        except (IndexError, ValueError):
            raise
    return OptionalURL(args, kwargs, rest)


@register.tag
def url(parser, token):
    """
    {% url [viewname] [args [kwargs]] %}
    """
